"""Command-line interface for the bank ledger."""

import sys

from ledger import Ledger

USAGE = (
    "usage: cli.py {open <owner>|balance <id>|deposit <id> <cents>"
    "|withdraw <id> <cents>|transfer <src> <dst> <cents>}"
)


def _parse_int(value):
    try:
        return int(value)
    except (TypeError, ValueError):
        return None


def main(argv, ledger):
    """Run the CLI. Returns the process exit code."""
    if not argv:
        print(USAGE, file=sys.stderr)
        return 2

    cmd = argv[0]

    if cmd == "open":
        if len(argv) != 2:
            print(USAGE, file=sys.stderr)
            return 2
        acct_id = ledger.open_account(argv[1])
        print(f"account #{acct_id}")
        return 0

    if cmd == "balance":
        if len(argv) != 2:
            print(USAGE, file=sys.stderr)
            return 2
        acct_id = _parse_int(argv[1])
        bal = ledger.balance(acct_id) if acct_id is not None else None
        if bal is None:
            print("no such account", file=sys.stderr)
            return 1
        print(bal)
        return 0

    if cmd in ("deposit", "withdraw"):
        if len(argv) != 3:
            print(USAGE, file=sys.stderr)
            return 2
        acct_id = _parse_int(argv[1])
        cents = _parse_int(argv[2])
        if acct_id is None or cents is None:
            print("failed", file=sys.stderr)
            return 1
        if cmd == "deposit":
            ok = ledger.deposit(acct_id, cents)
        else:
            ok = ledger.withdraw(acct_id, cents)
        if ok:
            print("ok")
            return 0
        print("failed", file=sys.stderr)
        return 1

    if cmd == "transfer":
        if len(argv) != 4:
            print(USAGE, file=sys.stderr)
            return 2
        src = _parse_int(argv[1])
        dst = _parse_int(argv[2])
        cents = _parse_int(argv[3])
        if src is None or dst is None or cents is None:
            print("failed", file=sys.stderr)
            return 1
        if ledger.transfer(src, dst, cents):
            print("ok")
            return 0
        print("failed", file=sys.stderr)
        return 1

    print(USAGE, file=sys.stderr)
    return 2


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:], Ledger("ledger.json")))

